   134	function removeWaypoint(transaction: OnyxEntry<Transaction>, currentIndex: string, isDraft?: boolean): Promise<void | void[]> {
   135	    // Index comes from the route params and is a string
   136	    const index = Number(currentIndex);
   137	    const existingWaypoints = transaction?.comment?.waypoints ?? {};
   138	    const totalWaypoints = Object.keys(existingWaypoints).length;
