        if (isOffline) {
            setOptimisticWaypoints(newWaypoints);

            // We need to re-validate the waypoints to check for duplicates
            const newValidatedWaypoints = TransactionUtils.getValidWaypoints(newWaypoints);
            if (Object.keys(newValidatedWaypoints).length < 2) {
                setShouldShowAtLeastTwoDifferentWaypointsError(true);
