        // and replace it with an empty object, so that it's not detected as a duplicate.
        // Then we can update the waypoints with the new order.
        // The empty waypoint will be removed on the backend.
        let emptyWaypointIndex = from;
        waypointsList.forEach((key, index) => {
            // We need to find the original index of the waypoint that was moved
            // by comparing the keyForList, since the order of the waypoints has changed.
            if (waypoints[key].keyForList === data[to].keyForList) {
